use std::{io::Write,process::{Command,Stdio}};
#[test] fn uci_handshake_and_bestmove(){let mut child=Command::new(env!("CARGO_BIN_EXE_ferrum")).stdin(Stdio::piped()).stdout(Stdio::piped()).spawn().unwrap();child.stdin.as_mut().unwrap().write_all(b"uci\nisready\nposition startpos moves e2e4\ngo depth 3\nquit\n").unwrap();let out=child.wait_with_output().unwrap();let text=String::from_utf8_lossy(&out.stdout);assert!(text.contains("id name ferrum"));assert!(text.contains("uciok"));assert!(text.contains("readyok"));let best=text.lines().find(|line|line.starts_with("bestmove ")).unwrap();assert!(!best.contains("0000"));}
